        UPDATE events
        SET profile_id = CASE session_id
          WHEN {p1:String} THEN {p2:String}
WHEN {p3:String} THEN {p4:String}
WHEN {p5:String} THEN {p6:String}
        END
        WHERE (project_id, session_id) IN (({p7:String}, {p8:String}), ({p9:String}, {p10:String}), ({p11:String}, {p12:String}))
          AND created_at > now() - INTERVAL 6 HOURS
